//! Conformance gate against the maximized tier-A vector corpus (26 vectors).
//!
//! For every vector this asserts: (1) the recomputed JCS preimage matches the
//! stored bytes; (2) `verify` returns `Ok(true)`; (3) a deterministic re-sign
//! reproduces the stored HMAC and Ed25519 signatures byte-for-byte; (4) a
//! tampered payload yields `Ok(false)` (not an error); (5) schema detection
//! reports V4. A synthetic legacy record asserts `Err(UnsupportedSchemaV3)`.
//!
//! The corpus is generated by `scripts/gen_vectors.py` against the Python
//! `core/seal` reference; the static list below must mirror its output (the
//! `include_str!` macro needs compile-time paths, so it cannot glob). The
//! `vectors_count_matches_index` test guards against drift between this list
//! and `INDEX.json`.

use apohara_sealchain_core::layers::ed25519 as ed_layer;
use apohara_sealchain_core::schema::SchemaVersion;
use apohara_sealchain_core::{
    build_preimage, detect_schema, seal_deterministic, verify, SealError,
};
use serde_json::Value;

